1	package campaign
2	
3	import (
4		"context"
5		"errors"
6		"strconv"
7		"strings"
8		"time"
9		"unicode/utf8"
10	
11		"github.com/jackc/pgx/v5"
12	
13		"github.com/Berk-Cinek/Mini-Ad-Campaign/backend/internal/httpx"
14	)
15	
16	type Service struct {
17		repo *Repository
18	}
19	
20	func NewService(repo *Repository) *Service {
21		return &Service{repo: repo}
22	}
23	
24	func (s *Service) Create(ctx context.Context, in CreateInput) (Campaign, error) {
25		title := strings.TrimSpace(in.Title)
26		if title == "" {
27			return Campaign{}, httpx.Invalid("title is required")
28		}
29		if utf8.RuneCountInString(title) > 200 {
30			return Campaign{}, httpx.Invalid("title must be at most 200 characters")
31		}
32	
33		budget, err := strconv.ParseInt(string(in.Budget), 10, 64)
34		if err != nil || budget < 1 {
35			return Campaign{}, httpx.Invalid("budget must be a whole number >= 1")
36		}
37	
38		// A missing/null JSON date decodes to time.Time's zero value (0001-01-01),
39		// not an error, so it must be checked explicitly — otherwise an omitted
40		// start_date passes both After() checks below (zero time is before any
41		// real end_date, and any real end_date is after "now").
42		if in.StartDate.IsZero() {
43			return Campaign{}, httpx.Invalid("start_date is required")
44		}
45		if in.EndDate.IsZero() {
46			return Campaign{}, httpx.Invalid("end_date is required")
47		}
48	
49		if !in.EndDate.After(in.StartDate) {
50			return Campaign{}, httpx.Invalid("end_date must be after start_date")
51		}
52		if !in.EndDate.After(time.Now()) {
53			return Campaign{}, httpx.Invalid("end_date must be in the future")
54		}
55	
56		return s.repo.Create(ctx, Campaign{
57			Title:     title,
58			Budget:    budget,
59			StartDate: in.StartDate.UTC(),
60			EndDate:   in.EndDate.UTC(),
61		})
62	}
63	
64	func (s *Service) List(ctx context.Context) ([]Campaign, error) {
65		return s.repo.List(ctx)
66	}
67	
68	func (s *Service) Get(ctx context.Context, id int64) (Campaign, error) {
69		c, err := s.repo.GetByID(ctx, id)
70		if errors.Is(err, pgx.ErrNoRows) {
71			return Campaign{}, httpx.NotFound("campaign not found")
72		}
73		if err != nil {
74			return Campaign{}, err
75		}
76		return c, nil
77	}
78	
79	func (s *Service) Update(ctx context.Context, id int64, in UpdateInput) (Campaign, error) {
80		current, err := s.repo.GetByID(ctx, id)
81		if errors.Is(err, pgx.ErrNoRows) {
82			return Campaign{}, httpx.NotFound("campaign not found")
83		}
84		if err != nil {
85			return Campaign{}, err
86		}
87	
88		if current.Status == StatusCompleted {
89			return Campaign{}, httpx.Conflict("completed campaigns cannot be edited")
90		}
91	
92		datesTouched := in.StartDate != nil || in.EndDate != nil
93		if datesTouched && current.Status != StatusPaused {
94			return Campaign{}, httpx.Conflict("dates can only be changed while the campaign is paused")
95		}
96	
97		var newTitle *string
98		if in.Title != nil {
99			title := strings.TrimSpace(*in.Title)
100			if title == "" {
101				return Campaign{}, httpx.Invalid("title is required")
102			}
103			if utf8.RuneCountInString(title) > 200 {
104				return Campaign{}, httpx.Invalid("title must be at most 200 characters")
105			}
106			newTitle = &title
107		}
108	
109		var newBudget *int64
110		if in.Budget != nil {
111			budget, err := strconv.ParseInt(string(*in.Budget), 10, 64)
112			if err != nil || budget < 1 {
113				return Campaign{}, httpx.Invalid("budget must be a whole number >= 1")
114			}
115			// Comparing against the campaign's current state (spent), not a
116			// property of the value alone, so this is a conflict (409) like the
117			// completed/dates-while-active checks above, not an input error (400).
118			if budget < current.Spent {
119				return Campaign{}, httpx.Conflict("budget cannot be lower than spent")
120			}
121			newBudget = &budget
122		}
123	
124		var newStart, newEnd *time.Time
125		if datesTouched {
126			effectiveStart := current.StartDate
127			if in.StartDate != nil {
128				if in.StartDate.IsZero() {
129					return Campaign{}, httpx.Invalid("start_date cannot be empty")
130				}
131				effectiveStart = in.StartDate.UTC()
132				newStart = &effectiveStart
133			}
134			effectiveEnd := current.EndDate
135			if in.EndDate != nil {
136				if in.EndDate.IsZero() {
137					return Campaign{}, httpx.Invalid("end_date cannot be empty")
138				}
139				effectiveEnd = in.EndDate.UTC()
140				newEnd = &effectiveEnd
141			}
142			if !effectiveEnd.After(effectiveStart) {
143				return Campaign{}, httpx.Invalid("end_date must be after start_date")
144			}
145			if !effectiveEnd.After(time.Now()) {
146				return Campaign{}, httpx.Invalid("end_date must be in the future")
147			}
148		}
149	
150		updated, err := s.repo.Update(ctx, id, newTitle, newBudget, newStart, newEnd)
151		if errors.Is(err, pgx.ErrNoRows) {
152			return Campaign{}, s.classifyUpdateConflict(ctx, id,
153				conflictCheck{func(c Campaign) bool { return c.Status == StatusCompleted }, "completed campaigns cannot be edited"},
154				conflictCheck{func(c Campaign) bool { return datesTouched && c.Status != StatusPaused }, "dates can only be changed while the campaign is paused"},
155				conflictCheck{func(c Campaign) bool { return newBudget != nil && *newBudget < c.Spent }, "budget cannot be lower than spent"},
156			)
157		}
158		if err != nil {
159			return Campaign{}, err
160		}
161		return updated, nil
162	}
163	
164	type conflictCheck struct {
165		failed  func(Campaign) bool
166		message string
167	}
168	
169	// classifyUpdateConflict explains why a conditional UPDATE (Update's PATCH,
170	// or the impression endpoint's Deduct) matched zero rows: re-reads the row
171	// and returns 404 if it's missing/deleted, otherwise runs the caller-supplied
172	// checks in order and returns the first one whose condition still holds as a
173	// 409 — falling back to a generic conflict message if none match (only
174	// reachable if the row changed again between the original write attempt and
175	// this re-read).
176	func (s *Service) classifyUpdateConflict(ctx context.Context, id int64, checks ...conflictCheck) error {
177		current, err := s.repo.GetByID(ctx, id)
178		if errors.Is(err, pgx.ErrNoRows) {
179			return httpx.NotFound("campaign not found")
180		}
181		if err != nil {
182			return err
183		}
184		for _, check := range checks {
